package com.craftworld3d.ui;
import android.graphics.*;import android.view.*;import com.craftworld3d.player.Player;
/** Resolution-independent touch HUD; game input is deliberately kept separate from rendering. */
public final class HudView extends View {final Player p;final com.craftworld3d.world.World world;final Paint q=new Paint(1);float sx,sy,lx,ly;boolean forward,left,right,back;
 public HudView(android.content.Context c,Player p,com.craftworld3d.world.World w){super(c);this.p=p;this.world=w;q.setTypeface(Typeface.DEFAULT_BOLD);setFocusable(true);}
 protected void onDraw(Canvas c){super.onDraw(c);int w=getWidth(),h=getHeight();q.setColor(0x99ffffff);q.setStyle(Paint.Style.STROKE);q.setStrokeWidth(4);c.drawCircle(100,h-110,62,q);c.drawCircle(w-105,h-110,48,q);q.setStyle(Paint.Style.FILL);q.setColor(Color.WHITE);q.setTextSize(22);c.drawText("CRAFTWORLD 3D",24,36,q);c.drawText("❤ "+p.health+"     🍗 "+p.hunger,24,66,q);c.drawText("JUMP",w-180,h-170,q);c.drawText("☰",w-55,42,q);c.drawText("▣",w/2-10,h-30,q);q.setTextSize(14);c.drawText("Day "+(p.x==p.x?"" : ""),w/2-22,30,q);}
 public boolean onTouchEvent(android.view.MotionEvent e){float x=e.getX(),y=e.getY();if(e.getAction()==0){sx=x;sy=y;lx=x;ly=y;if(x<220&&y>getHeight()-220)forward=true;if(x>getWidth()-220&&y>getHeight()-220)p.update(0,true,false,false,false,true);invalidate();return true;}if(e.getAction()==2){float dx=x-lx,dy=y-ly;if(sx<220&&sy>getHeight()-220){forward=dy<-10;back=dy>10;left=dx<-10;right=dx>10;p.update(.016f,forward,back,left,right,false);}else{p.yaw+=dx*.008f;p.pitch=Math.max(-1.3f,Math.min(1.3f,p.pitch-dy*.006f));}lx=x;ly=y;invalidate();return true;}if(e.getAction()==1){if(Math.abs(x-getWidth()/2)<100&&Math.abs(y-getHeight()/2)<100){int bx=(int)Math.floor(p.x+Math.sin(p.yaw)*3),bz=(int)Math.floor(p.z-Math.cos(p.yaw)*3),by=(int)Math.floor(p.y);if(world.getBlock(bx,by,bz)==com.craftworld3d.world.BlockType.AIR)world.setBlock(bx,by,bz,com.craftworld3d.world.BlockType.fromId(p.selected+1));else world.setBlock(bx,by,bz,com.craftworld3d.world.BlockType.AIR);}forward=back=left=right=false;invalidate();return true;}return true;}
}
